ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    struct hid_gadget *hid;
    ssize_t ret = 0;
    int status;

    hid = file->private_data;
    if (!hid)
        return -ENODEV;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock_irq(&hid->write_queue_lock);

    while (!hid->write_pending) {
        status = wait_event_interruptible(hid->write_queue_wait, hid->write_pending);
        if (status < 0) {
            ret = status;
            goto out;
        }
    }

    if (copy_from_user(hid->write_req->buf, buffer, count)) {
        ret = -EFAULT;
        goto out;
    }

    hid->write_req->length = count;
    usb_ep_queue(hid->ep_out, hid->write_req, GFP_ATOMIC);
    hid->write_pending = false;

    ret = count;
    wake_up(&hid->write_queue_wait);

out:
    spin_unlock_irq(&hid->write_queue_lock);
    return ret;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    struct hid_request *req;
    ssize_t bytes_written = 0;
    int ret;

    if (!access_ok(VERIFY_READ, buffer, count))
        return -EFAULT;

    spin_lock(&write_lock);

    while (write_pending) {
        wait_event_interruptible(write_queue, !write_pending);
        if (signal_pending(current)) {
            spin_unlock(&write_lock);
            return -ERESTARTSYS;
        }
    }

    req = hid_request_alloc(count);
    if (!req) {
        spin_unlock(&write_lock);
        return -ENOMEM;
    }

    if (copy_from_user(req->data, buffer, count)) {
        hid_request_free(req);
        spin_unlock(&write_lock);
        return -EFAULT;
    }

    write_pending = true;
    usb_submit_request(req);
    spin_unlock(&write_lock);

    bytes_written = count;

    wake_up_all(&write_queue);

    return bytes_written;
}

