        wait_event_interruptible(write_queue_wait, !write_pending);
        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto unlock;
        }
    }

    req = kmalloc(sizeof(*req), GFP_ATOMIC);
    if (!req) {
        ret = -ENOMEM;
        goto unlock;
    }

