        goto unlock;
    }

    write_pending = true;

unlock:
    spin_unlock(&write_queue_lock);
    return ret ? ret : count;
}

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp) {
    ssize_t ret = 0;
    struct hid_gadget *hid_gadget = file->private_data;
    DECLARE_WAITQUEUE(wait, current);
    int err = 0;

    if (!access_ok(buffer, count))
        return -EFAULT;

    spin_lock_irq(&hid_gadget->write_queue_lock);

    add_wait_queue(&hid_gadget->write_queue, &wait);

    while (hid_gadget->write_pending) {
        set_current_state(TASK_INTERRUPTIBLE);
        spin_unlock_irq(&hid_gadget->write_queue_lock);

        schedule();

        spin_lock_irq(&hid_gadget->write_queue_lock);
        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }
    }

    hid_gadget->write_pending = true;

    spin_unlock_irq(&hid_gadget->write_queue_lock);

    err = copy_from_user(hid_gadget->request_buffer, buffer, count);
    if (err) {
        ret = -EFAULT;
        goto error;
    }

    hid_gadget->request_length = count;

    err = usb_submit_urb(hid_gadget->write_urb, GFP_KERNEL);
    if (err) {
        ret = err;
        goto error;
    }

    return count;

error:
    hid_gadget->write_pending = false;
    wake_up_interruptible(&hid_gadget->write_queue);
out:
    set_current_state(TASK_RUNNING);
    remove_wait_queue(&hid_gadget->write_queue, &wait);
    return ret;
}
